using System;
using System.Collections.Generic;
using System.Drawing;
namespace Downfield {
public partial class GameForm {
 List<ClubPlayer> confirmPlayers=new List<ClubPlayer>();
 List<ClubPlayer> MentionedPlayers(string text){List<ClubPlayer> found=new List<ClubPlayer>();foreach(int team in new int[]{franchise.UserTeam,-99})foreach(ClubPlayer p in franchise.Players)if((team==-99?p.Team!=franchise.UserTeam:p.Team==team)&&p.Name.Length>0&&text.IndexOf(p.Name,StringComparison.OrdinalIgnoreCase)>=0&&!found.Exists(q=>q.Name==p.Name)){found.Add(p);if(found.Count==3)return found;}return found;}
 void CaptureConfirmPlayers(string detail){confirmPlayers=new List<ClubPlayer>();if(screen=="draft"&&selection<franchise.Prospects.Count){confirmPlayers.Add(franchise.Prospects[selection]);}else if(screen=="freeagents"||screen=="offers"){List<ClubPlayer> list=FrontPlayers();if(screen=="offers"){ClubPlayer outgoing=franchise.Players.Find(p=>p.Id==tradePlayer);if(outgoing!=null)confirmPlayers.Add(outgoing);}if(selection>=0&&selection<list.Count)confirmPlayers.Add(list[selection]);}else if(screen=="player"&&SelectedPlayer!=null)confirmPlayers.Add(SelectedPlayer);else confirmPlayers=MentionedPlayers(detail);}
 List<ClubPlayer> FrontRowPeople(int index,List<string> rows){List<ClubPlayer> result=new List<ClubPlayer>();if(screen=="roster"||screen=="trade"||screen=="freeagents"||screen=="offers"||screen=="teamroster"){List<ClubPlayer> players=FrontPlayers();if(index<players.Count)result.Add(players[index]);}else if(screen=="injuries"){List<ClubPlayer> injured=franchise.Squad(franchise.UserTeam).FindAll(p=>p.InjuryWeeks>0);if(index<injured.Count)result.Add(injured[index]);}else if(screen=="lineup"&&SelectedPlayer!=null){List<int> slots=franchise.EligibleSlots(SelectedPlayer);if(index<slots.Count){ClubPlayer current=franchise.Starter(franchise.UserTeam,slots[index]);if(current!=null)result.Add(current);}}else if(screen=="news"&&index<rows.Count)result=MentionedPlayers(rows[index]);return result;}
 void FrontProfileRow(string text,int index,float y,bool chosen,List<string> rows){List<ClubPlayer> people=FrontRowPeople(index,rows);float left=56;foreach(ClubPlayer p in people){PlayerPortrait(p,left,y+3,42);left+=40;}TextAt(Clip(text,(int)((778-left)/12)),left+(people.Count>0?6:0),y+15,12,chosen?Gold:White);}
 ClubPlayer AwardPortrait(SeasonAward award){ClubPlayer player=franchise.Players.Find(p=>p.Id==award.PlayerId&&award.PlayerId>0);if(player!=null)return player;player=franchise.Players.Find(p=>p.Name==award.Winner&&p.Team==award.Team);if(player!=null)return player;if(award.Type=="CHAMPIONSHIP")return null;return new ClubPlayer{Id=award.PlayerId,Name=award.Winner,Team=award.Team,Role=award.Role,Number=award.Number,OVR=award.OVR,Speed=award.Speed,Hands=award.Hands,Power=award.Power,Slot=-1};}
 ClubPlayer BetaRowPerson(int index){if(screen=="leaders"){List<SeasonProduction> leaders=new List<SeasonProduction>(franchise.Production);leaders.Sort((a,b)=>b.OffenseScore.CompareTo(a.OffenseScore));if(index<leaders.Count){SeasonProduction row=leaders[index];return franchise.Players.Find(p=>p.Id==row.PlayerId)??new ClubPlayer{Name=row.Name,Role=row.Role,Team=row.Team,Number=0,OVR=0};}}if(screen=="awards"){string type=AwardTypes[awardCategory];List<SeasonAward> awards=franchise.Awards.FindAll(a=>a.Type==type);awards.Reverse();if(index<awards.Count)return AwardPortrait(awards[index]);}return null;}
 void DrawConfirmPeople(){Panel(70,190,1140,468);TextAt(confirmTitle,100,218,24,Gold);TextAt(Clip(confirmDetail,88),100,266,12,White);for(int i=0;i<confirmPlayers.Count&&i<2;i++){ClubPlayer p=confirmPlayers[i];float x=100+i*550;Rect(x,313,520,205,Color.FromArgb(35,45,58));PlayerPortrait(p,x+15,335,126);TextAt(p.Name,x+143,339,18,Gold);TextAt(p.Role+" / "+p.OVR+" OVR",x+143,378,14,White);TextAt("SPEED "+p.Speed+" / HANDS "+p.Hands,x+143,414,11,Mint);TextAt("SALARY $"+p.Salary+" / "+(p.Team<0?3:p.Years)+" YEARS",x+143,451,11,White);TextAt(p.Team==-2?"DRAFT PROSPECT":p.Team<0?"FREE AGENT":franchise.Teams[p.Team].Mascot,x+143,483,11,Muted);}for(int i=0;i<2;i++){Button(i==0?"CANCEL":"CONFIRM","",100+i*550,570,520,selection==i);HitArea(100+i*550,570,520,58,i);}TextAt(Clip(franchise.Notice,98),40,718,11,Mint);}
}
}
